<?php $a=admin_current(); ?>
<?php if(!in_array($a['role'],['owner','manager'],true)): ?><p class="notice">این بخش برای مدیرکل و مدیر اجرایی است.</p><?php else: $prefs=admin_notice_prefs((int)$a['id']); ?>
<section class="panel narrow" data-admin-push data-key="<?= esc(setting('push_vapid_public')) ?>" data-csrf="<?= esc(csrf()) ?>"><h2>اعلان مرورگر مدیریت</h2><p>روی هر دستگاه یک بار فعال کنید. گزارش روزانه و رویدادهای انتخاب‌شده با Cron ارسال می‌شوند. در آیفون، برنامه را به صفحه اصلی اضافه کنید.</p><?php if(!push_available()): ?><p class="error">ابتدا اعلان مرورگر را در بخش «یادآوری، اعلان و صف» فعال کنید.</p><?php endif; ?><label class="check"><input type="checkbox" data-admin-push-consent> با دریافت اعلان روی این دستگاه موافقم.</label><div class="button-row"><button type="button" data-admin-push-enable>فعال‌سازی این دستگاه</button><button type="button" class="secondary" data-admin-push-off>خاموش کردن همه دستگاه‌های من</button></div><p data-admin-push-status role="status"></p><h3>رویدادهای موردنظر</h3><form data-admin-push-prefs><?php foreach(admin_notice_events() as $key=>$label): ?><label class="check"><input type="checkbox" name="<?= esc($key) ?>"<?= checked_attr(!empty($prefs[$key])) ?>><?= esc($label) ?></label><?php endforeach; ?><label>ساعت گزارش روزانه (مشترک مدیران)<select name="summary_hour"><?php for($h=0;$h<24;$h++): ?><option value="<?= $h ?>"<?= selected_attr($h===setting_int('platform_summary_hour',21,0,23)) ?>><?= fa_number(sprintf('%02d:00',$h)) ?></option><?php endfor; ?></select></label><button>ذخیره ترجیحات من</button></form></section>
<?php endif; ?>
